R,C=22,26
g=[[0]*C for _ in range(R)]
def rect_border(r0,r1,c0,c1,color):
    for c in range(c0,c1+1): g[r0][c]=g[r1][c]=color
    for r in range(r0,r1+1): g[r][c0]=g[r][c1]=color
def fill_check(r0,r1,c0,c1,color):
    for r in range(r0,r1+1):
        for c in range(c0,c1+1):
            if (r-r0+c-c0)%2==0: g[r][c]=color
rect_border(1,6,3,11,1); fill_check(2,5,4,10,4)
rect_border(10,13,2,5,2); fill_check(11,12,3,4,8)
rect_border(9,16,11,21,3); fill_check(10,15,12,20,5)
print('\n'.join(' '.join(map(str,row)) for row in g))
